import { useRef } from 'react';
import type { ApiFormQuestion } from '@/api/types.js';
import { Icon } from '@/components/ui/Icon.js';
import { inputClass, invalidClass, textareaClass } from '@/components/ui/fieldStyles.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { COUNT_FROM, RATING_POINTS, textMax, type AnswerValue } from './answers.js';
import styles from './FormScreen.module.css';

/**
 * One question of a form: its legend, the error when Send found it
 * unanswered, and its control (design §3.2). A `<fieldset>` with no border,
 * so the whole group is named by its question and disabled with the form
 * while it is being sent.
 */
export function Question({
  question,
  idBase,
  value,
  error,
  disabled,
  onChange,
}: {
  question: ApiFormQuestion;
  /** Unique on the page, for the ids that tie the parts together. */
  idBase: string;
  value: AnswerValue | undefined;
  error: MessageKey | undefined;
  /** While the answers are being sent. */
  disabled: boolean;
  onChange: (value: AnswerValue) => void;
}): React.JSX.Element {
  const legendId = `${idBase}-l`;
  const helpId = `${idBase}-h`;
  const errorId = `${idBase}-e`;
  const endsId = `${idBase}-ends`;
  const help = question.type === 'multi' ? t('form.chooseAll') : undefined;
  const describedBy =
    [
      help === undefined ? '' : helpId,
      question.type === 'rating' ? endsId : '',
      error === undefined ? '' : errorId,
    ]
      .filter((id) => id !== '')
      .join(' ') || undefined;
  const group = {
    'aria-labelledby': legendId,
    'aria-describedby': describedBy,
    'aria-required': question.required || undefined,
    'aria-invalid': error === undefined ? undefined : true,
  };

  return (
    <fieldset
      className={cx(styles.q, error !== undefined && styles.qInvalid)}
      data-invalid={error !== undefined}
      disabled={disabled}
    >
      <legend className={styles.qLegend} id={legendId}>
        <span className={styles.qText} dir="auto">
          {question.prompt}
          {question.required ? (
            <span className={styles.req} aria-hidden="true">
              {' *'}
            </span>
          ) : (
            <>
              {' '}
              <bdi dir="ltr" className={styles.qOptional}>
                {t('form.optional')}
              </bdi>
            </>
          )}
        </span>
        {help !== undefined && (
          <span className={styles.qHelp} id={helpId}>
            <bdi dir="ltr">{help}</bdi>
          </span>
        )}
      </legend>
      {error !== undefined && (
        <p className={styles.qError} id={errorId}>
          <Icon name="info" size={16} weight={2} />
          <bdi dir="ltr">{t(error)}</bdi>
        </p>
      )}
      {question.type === 'single' && (
        <Choices question={question} multi={false} value={value} onChange={onChange} group={group} />
      )}
      {question.type === 'multi' && (
        <Choices question={question} multi value={value} onChange={onChange} group={group} />
      )}
      {question.type === 'rating' && (
        <Rating value={value} onChange={onChange} group={group} endsId={endsId} />
      )}
      {(question.type === 'short_text' || question.type === 'long_text') && (
        <TextAnswer question={question} value={value} onChange={onChange} group={group} error={error} />
      )}
    </fieldset>
  );
}

type Group = Record<string, string | boolean | undefined>;

/**
 * Arrow keys inside a radio group move the choice, as in any radio group:
 * down and "forward" (right in a left-to-right layout, left in a
 * right-to-left one) to the next, up and back to the previous.
 */
function step(event: React.KeyboardEvent, rtl: boolean): -1 | 1 | 'first' | 'last' | undefined {
  switch (event.key) {
    case 'ArrowDown':
      return 1;
    case 'ArrowUp':
      return -1;
    case 'ArrowRight':
      return rtl ? -1 : 1;
    case 'ArrowLeft':
      return rtl ? 1 : -1;
    case 'Home':
      return 'first';
    case 'End':
      return 'last';
    default:
      return undefined;
  }
}

function isRtl(element: Element): boolean {
  return getComputedStyle(element).direction === 'rtl';
}

/** Moves a radio group's choice by a key, and focus with it. */
function moveRadio<T>(
  event: React.KeyboardEvent<HTMLElement>,
  items: readonly T[],
  current: number,
  choose: (item: T) => void,
  buttons: (HTMLButtonElement | null)[],
): void {
  const by = step(event, isRtl(event.currentTarget));
  if (by === undefined) return;
  event.preventDefault();
  // From the one chosen, or, with none chosen yet, the one that has focus.
  const focused = buttons.indexOf(event.currentTarget as HTMLButtonElement);
  const from = current >= 0 ? current : Math.max(focused, 0);
  const next =
    by === 'first' ? 0 : by === 'last' ? items.length - 1 : (from + by + items.length) % items.length;
  const item = items[next];
  if (item === undefined) return;
  choose(item);
  buttons[next]?.focus();
}

function Choices({
  question,
  multi,
  value,
  onChange,
  group,
}: {
  question: ApiFormQuestion;
  multi: boolean;
  value: AnswerValue | undefined;
  onChange: (value: AnswerValue) => void;
  group: Group;
}): React.JSX.Element {
  const options = question.options ?? [];
  const chosen = multi ? (Array.isArray(value) ? value : []) : typeof value === 'string' ? [value] : [];
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const current = multi ? -1 : options.findIndex((option) => option.id === value);

  return (
    <div className={styles.choices} role={multi ? 'group' : 'radiogroup'} {...group}>
      {options.map((option, index) => {
        const on = chosen.includes(option.id);
        return (
          <button
            key={option.id}
            ref={(element) => {
              buttons.current[index] = element;
            }}
            type="button"
            role={multi ? 'checkbox' : 'radio'}
            aria-checked={on}
            className={cx(styles.choice, on && styles.choiceOn)}
            // One stop for the whole radio group: the chosen one, or the first.
            tabIndex={multi ? 0 : (current < 0 ? index === 0 : on) ? 0 : -1}
            onClick={() => {
              if (!multi) onChange(option.id);
              else onChange(on ? chosen.filter((id) => id !== option.id) : [...chosen, option.id]);
            }}
            onKeyDown={
              multi
                ? undefined
                : (event) => {
                    moveRadio(
                      event,
                      options,
                      current,
                      (next) => {
                        onChange(next.id);
                      },
                      buttons.current,
                    );
                  }
            }
          >
            <span className={multi ? styles.tick : styles.radio} aria-hidden="true">
              {multi && on && <Icon name="check" size={14} weight={2.6} />}
            </span>
            <span className={styles.choiceText} dir="auto">
              {option.label}
            </span>
          </button>
        );
      })}
    </div>
  );
}

function Rating({
  value,
  onChange,
  group,
  endsId,
}: {
  value: AnswerValue | undefined;
  onChange: (value: AnswerValue) => void;
  group: Group;
  endsId: string;
}): React.JSX.Element {
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const current = RATING_POINTS.findIndex((point) => point === value);
  return (
    <>
      <div className={styles.scale} role="radiogroup" {...group}>
        {RATING_POINTS.map((point, index) => {
          const on = point === value;
          return (
            <button
              key={point}
              ref={(element) => {
                buttons.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={on}
              aria-label={t('form.ratingOf', { value: point })}
              className={cx(styles.point, on && styles.pointOn)}
              tabIndex={(current < 0 ? index === 0 : on) ? 0 : -1}
              onClick={() => {
                onChange(point);
              }}
              onKeyDown={(event) => {
                moveRadio(
                  event,
                  RATING_POINTS,
                  current,
                  (next) => {
                    onChange(next);
                  },
                  buttons.current,
                );
              }}
            >
              {point}
            </button>
          );
        })}
      </div>
      <div className={styles.scaleEnds} id={endsId}>
        <bdi dir="ltr">{t('form.ratingLow')}</bdi>
        <bdi dir="ltr">{t('form.ratingHigh')}</bdi>
      </div>
    </>
  );
}

/** Enter in a one-line answer moves on to the next control, and never sends the form. */
function focusNext(from: HTMLElement): void {
  const form = from.closest('form');
  if (form === null) return;
  const controls = [
    ...form.querySelectorAll<HTMLElement>(
      'button:not([disabled]), input:not([disabled]), textarea:not([disabled])',
    ),
  ].filter((element) => element.tabIndex >= 0);
  const next = controls[controls.indexOf(from) + 1];
  next?.focus();
}

function TextAnswer({
  question,
  value,
  onChange,
  group,
  error,
}: {
  question: ApiFormQuestion;
  value: AnswerValue | undefined;
  onChange: (value: AnswerValue) => void;
  group: Group;
  error: MessageKey | undefined;
}): React.JSX.Element {
  const text = typeof value === 'string' ? value : '';
  const max = textMax(question);
  const shared = {
    ...group,
    dir: 'auto',
    maxLength: max,
    value: text,
    onChange: (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      onChange(event.target.value);
    },
  };
  return (
    <>
      {question.type === 'short_text' ? (
        <input
          {...shared}
          type="text"
          className={cx(inputClass, styles.text, error !== undefined && invalidClass)}
          enterKeyHint="next"
          onKeyDown={(event) => {
            if (event.key !== 'Enter') return;
            event.preventDefault();
            focusNext(event.currentTarget);
          }}
        />
      ) : (
        <textarea
          {...shared}
          rows={4}
          className={cx(textareaClass, styles.text, styles.long, error !== undefined && invalidClass)}
        />
      )}
      {text.length >= max * COUNT_FROM && (
        <span className={styles.count} aria-live="polite">
          {t('form.count', { count: text.length, max })}
        </span>
      )}
    </>
  );
}
