import { useCallback, useEffect, useId, useRef, useState } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { ApiError } from '@/api/errors.js';
import { newIdempotencyKey } from '@/api/client.js';
import { forms as formsApi } from '@/api/endpoints.js';
import type { ApiForm } from '@/api/types.js';
import { Button } from '@/components/ui/Button.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { prefersReducedMotion } from '@/components/ui/motionPrefs.js';
import { Toast } from '@/components/ui/Toast.js';
import { dirOf } from '@/features/assistant/richText.js';
import { accountAddress } from '@/features/auth/hiddenEmail.js';
import { useAuth } from '@/features/auth/session.js';
import { noteFormAnswered } from '@/features/inbox/inbox.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { longDate } from '@/lib/format.js';
import {
  answerInput,
  closedOn,
  keepFitting,
  minutesFor,
  missingAnswers,
  type AnswerValue,
  type Answers,
} from './answers.js';
import { dropDraft, readDraft, saveDraft } from './draft.js';
import { Question } from './Question.js';
import styles from './FormScreen.module.css';

/** Answers are kept on the device this long after the last change (design §3.5). */
const DRAFT_SAVE_MS = 400;

type NotSent = 'offline' | 'server' | 'invalid';

/** Where the screen is. The form itself only while it can be answered. */
type Phase =
  | { kind: 'loading' }
  | { kind: 'cannotOpen'; offline: boolean }
  | { kind: 'gone' }
  | { kind: 'open'; form: ApiForm }
  | { kind: 'sent'; form: ApiForm }
  | { kind: 'answered'; form: ApiForm | undefined; answeredAt: string | undefined }
  | { kind: 'closed'; form: ApiForm | undefined };

/** Today's calendar day here, YYYY-MM-DD, to tell a closing day that has passed. */
function todayIso(): string {
  const now = new Date();
  const pad = (n: number): string => String(n).padStart(2, '0');
  return `${String(now.getFullYear())}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}

/** A calendar day as a sentence's date, read at midday so no zone moves it a day. */
function dayLabel(day: string): string {
  return longDate(`${day}T12:00:00Z`);
}

/**
 * A short form sent with a notification (design §3), at /forms/:formId.
 *
 * The form is the server's, so it is read from the network, like a shared
 * notebook; only the answers being written are this device's, and they are
 * kept in IndexedDB until they are sent, so going offline or closing the app
 * loses nothing. Nothing is checked while typing: Send says what is missing,
 * under each question and in one line above the button, and takes focus to
 * the first. A failed send says why and keeps the answers; the learner sends
 * again by pressing, never by the app on its own, so "one answer" stays
 * something they did.
 */
export function FormScreen(): React.JSX.Element {
  const { formId = '' } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const user = useAuth((state) => state.user);
  const idBase = useId();

  const [phase, setPhase] = useState<Phase>({ kind: 'loading' });
  const [answers, setAnswers] = useState<Answers>({});
  const [errors, setErrors] = useState<Record<string, MessageKey>>({});
  const [sending, setSending] = useState(false);
  const [notSent, setNotSent] = useState<NotSent | undefined>();
  const [closedToast, setClosedToast] = useState(false);
  const [attempt, setAttempt] = useState(0);
  const keyRef = useRef<string | undefined>(undefined);
  const formRef = useRef<HTMLFormElement>(null);
  const outcomeRef = useRef<HTMLHeadingElement>(null);
  const moveFocus = useRef(false);

  // Read the form, and any answers kept from before.
  useEffect(() => {
    // An object, so the closure below sees the change made when it stops.
    const run = { live: true };
    void (async () => {
      const draft = await readDraft(formId).catch(() => undefined);
      try {
        const form = await formsApi.get(formId);
        if (!run.live) return;
        if (form.answered) {
          await dropDraft(formId);
          void noteFormAnswered(formId);
          setPhase({ kind: 'answered', form, answeredAt: form.answeredAt });
        } else if (!form.open) {
          await dropDraft(formId);
          setPhase({ kind: 'closed', form });
        } else {
          keyRef.current = draft?.idempotencyKey;
          setAnswers(draft === undefined ? {} : keepFitting(form, draft.answers));
          setPhase({ kind: 'open', form });
        }
      } catch (cause) {
        if (!run.live) return;
        if (cause instanceof ApiError && cause.kind === 'notFound') {
          await dropDraft(formId);
          setPhase({ kind: 'gone' });
        } else if (draft?.form !== undefined) {
          // Offline with answers kept: the form they were written against.
          keyRef.current = draft.idempotencyKey;
          setAnswers(keepFitting(draft.form, draft.answers));
          setPhase({ kind: 'open', form: draft.form });
        } else {
          setPhase({ kind: 'cannotOpen', offline: !(cause instanceof ApiError) || cause.kind === 'offline' });
        }
      }
    })();
    return () => {
      run.live = false;
    };
  }, [formId, attempt]);

  // Keep the answers on the device, a moment after the last change.
  const openForm = phase.kind === 'open' ? phase.form : undefined;
  const dirty = useRef(false);
  useEffect(() => {
    if (openForm === undefined || !dirty.current) return;
    const timer = window.setTimeout(() => {
      void saveDraft(formId, openForm, answers, keyRef.current);
    }, DRAFT_SAVE_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [answers, openForm, formId]);

  // The outcome's heading takes focus when it replaces the form.
  useEffect(() => {
    if (!moveFocus.current) return;
    moveFocus.current = false;
    outcomeRef.current?.focus();
  }, [phase]);

  const setAnswer = useCallback(
    (questionId: string, value: AnswerValue) => {
      dirty.current = true;
      // Different answers are a different request.
      keyRef.current = undefined;
      setNotSent(undefined);
      setAnswers((current) => {
        const next = { ...current, [questionId]: value };
        if (openForm !== undefined) {
          // An error goes the moment its question is answered.
          setErrors((shown) => {
            if (!(questionId in shown)) return shown;
            const still = missingAnswers(openForm, next);
            const rest = { ...shown };
            // eslint-disable-next-line @typescript-eslint/no-dynamic-delete -- a record keyed by question id
            if (!(questionId in still)) delete rest[questionId];
            return rest;
          });
        }
        return next;
      });
    },
    [openForm],
  );

  const leave = (): void => {
    if (location.key === 'default') void navigate('/', { replace: true });
    else void navigate(-1);
  };
  const toToday = (): void => {
    void navigate('/', { replace: true });
  };

  const send = async (form: ApiForm): Promise<void> => {
    if (sending) return;
    const missing = missingAnswers(form, answers);
    setErrors(missing);
    if (Object.keys(missing).length > 0) {
      // After the errors are drawn: the first unanswered question to the
      // top, and focus on its first control.
      window.requestAnimationFrame(() => {
        const first = formRef.current?.querySelector<HTMLElement>('[data-invalid="true"]');
        if (!first) return;
        first.scrollIntoView({ block: 'start', behavior: prefersReducedMotion() ? 'instant' : 'smooth' });
        first
          .querySelector<HTMLElement>('button[tabindex="0"], input, textarea')
          ?.focus({ preventScroll: true });
      });
      return;
    }
    setSending(true);
    setNotSent(undefined);
    const key = keyRef.current ?? newIdempotencyKey();
    keyRef.current = key;
    await saveDraft(formId, form, answers, key).catch(() => undefined);
    try {
      await formsApi.answer(formId, answerInput(form, answers), key);
      await dropDraft(formId);
      void noteFormAnswered(formId);
      moveFocus.current = true;
      setPhase({ kind: 'sent', form });
    } catch (cause) {
      const error = cause instanceof ApiError ? cause : undefined;
      if (error?.code === 'form_already_answered') {
        await dropDraft(formId);
        void noteFormAnswered(formId);
        moveFocus.current = true;
        setPhase({ kind: 'answered', form, answeredAt: undefined });
      } else if (error?.code === 'form_closed') {
        await dropDraft(formId);
        moveFocus.current = true;
        setClosedToast(true);
        setPhase({ kind: 'closed', form: { ...form, open: false } });
      } else if (error?.kind === 'notFound') {
        await dropDraft(formId);
        moveFocus.current = true;
        setPhase({ kind: 'gone' });
      } else if (error === undefined || error.kind === 'offline') {
        setNotSent('offline');
      } else if (error.kind === 'invalid' || error.status === 413) {
        setNotSent('invalid');
      } else {
        setNotSent('server');
      }
    } finally {
      setSending(false);
    }
  };

  // A right-to-left form turns the whole screen, back control included.
  const shownForm = phase.kind === 'open' ? phase.form : undefined;
  const screenDir = shownForm === undefined ? undefined : dirOf(shownForm.title);

  return (
    <main className={styles.screen} dir={screenDir}>
      <header className={styles.subHead}>
        <button type="button" className={styles.back} aria-label={t('action.back')} onClick={leave}>
          <Icon name="chevronLeft" size={22} weight={2} />
        </button>
      </header>
      {phase.kind === 'loading' && <Loading />}
      {phase.kind === 'open' && (
        <FormBody
          form={phase.form}
          idBase={idBase}
          formRef={formRef}
          answers={answers}
          errors={errors}
          sending={sending}
          notSent={notSent}
          email={user === null ? undefined : accountAddress(user)}
          onAnswer={setAnswer}
          onSend={() => {
            void send(phase.form);
          }}
        />
      )}
      {phase.kind === 'sent' && (
        <Outcome
          icon="check"
          kicker={phase.form.title}
          title={t('form.sentTitle')}
          body={
            phase.form.thanks !== undefined && phase.form.thanks !== ''
              ? phase.form.thanks
              : t('form.sentBody')
          }
          status
          titleRef={outcomeRef}
          actions={<Button onClick={toToday}>{t('form.back')}</Button>}
        />
      )}
      {phase.kind === 'answered' && (
        <Outcome
          icon="check"
          kicker={phase.form?.title}
          title={t('form.answeredTitle')}
          body={
            phase.answeredAt === undefined
              ? t('form.answeredBodyNoDate')
              : t('form.answeredBody', { date: longDate(phase.answeredAt) })
          }
          titleRef={outcomeRef}
          actions={
            <Button variant="secondary" onClick={toToday}>
              {t('form.back')}
            </Button>
          }
        />
      )}
      {phase.kind === 'closed' && (
        <Outcome
          icon="lock"
          quiet
          title={t('form.closedTitle')}
          body={(() => {
            const day = phase.form === undefined ? undefined : closedOn(phase.form, todayIso());
            return day === undefined
              ? t('form.closedBodyNoDate')
              : t('form.closedBody', { date: dayLabel(day) });
          })()}
          titleRef={outcomeRef}
          actions={
            <Button variant="secondary" onClick={toToday}>
              {t('form.back')}
            </Button>
          }
        />
      )}
      {phase.kind === 'gone' && (
        <Outcome
          icon="info"
          quiet
          title={t('form.goneTitle')}
          body={t('form.goneBody')}
          titleRef={outcomeRef}
          actions={
            <Button variant="secondary" onClick={toToday}>
              {t('form.back')}
            </Button>
          }
        />
      )}
      {phase.kind === 'cannotOpen' && (
        <Outcome
          icon={phase.offline ? 'wifiOff' : 'info'}
          quiet
          title={t('form.offlineTitle')}
          body={phase.offline ? t('form.offlineBody') : t('form.loadFailedBody')}
          titleRef={outcomeRef}
          actions={
            <>
              <Button
                variant="secondary"
                onClick={() => {
                  setPhase({ kind: 'loading' });
                  setAttempt((n) => n + 1);
                }}
              >
                {t('form.tryAgain')}
              </Button>
              <Button variant="ghost" onClick={toToday}>
                {t('form.back')}
              </Button>
            </>
          }
        />
      )}
      {closedToast && (
        <Toast
          message={t('form.closedWhileAnswering')}
          onDone={() => {
            setClosedToast(false);
          }}
        />
      )}
    </main>
  );
}

function Loading(): React.JSX.Element {
  return (
    <div className={styles.loading}>
      <span role="status" className="sr-only">
        {t('form.loading')}
      </span>
      <div className={styles.skel} aria-hidden="true">
        <span className={styles.skelTitle} />
        <span className={styles.skelLine} />
        <span className={cx(styles.skelLine, styles.skelShort)} />
      </div>
      <div className={cx(styles.skel, styles.skelQuestion)} aria-hidden="true">
        <span className={cx(styles.skelLine, styles.skelPrompt)} />
        <span className={styles.skelRow} />
        <span className={styles.skelRow} />
        <span className={styles.skelRow} />
      </div>
    </div>
  );
}

function Outcome({
  icon,
  quiet = false,
  kicker,
  title,
  body,
  status = false,
  titleRef,
  actions,
}: {
  icon: IconName;
  quiet?: boolean;
  kicker?: string | undefined;
  title: string;
  body: string;
  /** Announced as it appears (the answers were just sent). */
  status?: boolean;
  titleRef: React.Ref<HTMLHeadingElement>;
  actions: React.ReactNode;
}): React.JSX.Element {
  return (
    <div className={styles.outcome} role={status ? 'status' : undefined}>
      <EmptyState
        middle
        heading="h1"
        icon={icon}
        tone={quiet ? 'quiet' : 'accent'}
        kicker={kicker}
        title={title}
        body={body}
        titleRef={titleRef}
        actions={actions}
      />
    </div>
  );
}

function FormBody({
  form,
  idBase,
  formRef,
  answers,
  errors,
  sending,
  notSent,
  email,
  onAnswer,
  onSend,
}: {
  form: ApiForm;
  idBase: string;
  formRef: React.RefObject<HTMLFormElement | null>;
  answers: Answers;
  errors: Record<string, MessageKey>;
  sending: boolean;
  notSent: NotSent | undefined;
  email: string | undefined;
  onAnswer: (questionId: string, value: AnswerValue) => void;
  onSend: () => void;
}): React.JSX.Element {
  const count = form.questions.length;
  const required = form.questions.some((question) => question.required);
  const missing = Object.keys(errors).length;
  const titleId = `${idBase}-title`;
  const [before, after] = t('form.who').split('{email}');

  return (
    <form
      ref={formRef}
      className={cx(styles.form, sending && styles.sending)}
      noValidate
      aria-labelledby={titleId}
      aria-busy={sending || undefined}
      onSubmit={(event) => {
        event.preventDefault();
        onSend();
      }}
    >
      <div className={styles.formHead}>
        <h1 className={styles.formTitle} id={titleId} dir="auto" tabIndex={-1}>
          {form.title}
        </h1>
        {form.intro !== '' && (
          <p className={styles.formIntro} dir="auto">
            {form.intro}
          </p>
        )}
        <p className={styles.formMeta}>
          <bdi dir="ltr">
            {t('form.meta', { count, minutes: minutesFor(count) })}
            {required && (
              <>
                {' · '}
                <span className={styles.req} aria-hidden="true">
                  *
                </span>{' '}
                {t('form.metaRequired')}
              </>
            )}
          </bdi>
        </p>
      </div>
      <div className={styles.questions}>
        {form.questions.map((question, index) => (
          <Question
            key={question.id}
            question={question}
            idBase={`${idBase}-q${String(index)}`}
            value={answers[question.id]}
            error={errors[question.id]}
            disabled={sending}
            onChange={(next) => {
              onAnswer(question.id, next);
            }}
          />
        ))}
      </div>
      <div className={styles.sendArea}>
        {missing > 0 && (
          <p className={styles.summary} role="alert">
            <bdi dir="ltr">{t('form.missing', { count: missing })}</bdi>
          </p>
        )}
        {notSent !== undefined && (
          <p className={styles.notSent} role="alert">
            <Icon name={notSent === 'offline' ? 'wifiOff' : 'info'} size={18} weight={1.9} />
            <bdi dir="ltr">
              {t(
                notSent === 'offline'
                  ? 'form.notSentOffline'
                  : notSent === 'invalid'
                    ? 'form.notSentInvalid'
                    : 'form.notSentServer',
              )}
            </bdi>
          </p>
        )}
        <Button
          type="submit"
          variant="primary"
          size="large"
          block
          aria-disabled={sending || undefined}
          className={cx(sending && styles.busy)}
        >
          {sending && <span className={styles.spinner} aria-hidden="true" />}
          {sending ? t('form.sending') : notSent !== undefined ? t('form.tryAgain') : t('form.send')}
        </Button>
        {email !== undefined && (
          <p className={styles.who}>
            <bdi dir="ltr">
              {before}
              <strong>{email}</strong>
              {after}
            </bdi>
          </p>
        )}
      </div>
    </form>
  );
}
