/**
 * Answers not sent yet stay on this device until they are (design §3.5):
 * going offline, closing the app or a failed send never loses them. They
 * live in meta `formDrafts` by form id, so signing out takes them with the
 * rest of the account's local data, and are deleted once the form is sent,
 * found answered or found closed.
 */
import type { ApiForm } from '@/api/types.js';
import { db, getMeta, setMeta, type FormDraft } from '@/db/schema.js';
import type { Answers } from './answers.js';

export async function readDraft(formId: string): Promise<FormDraft | undefined> {
  return (await getMeta('formDrafts'))[formId];
}

/**
 * Keeps the answers (and the form they belong to). Changed answers drop the
 * idempotency key, so a send after a change is a new request; the server
 * refuses a second answer anyway.
 */
export async function saveDraft(
  formId: string,
  form: ApiForm,
  answers: Answers,
  idempotencyKey?: string,
): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    const drafts = await getMeta('formDrafts');
    const next: FormDraft = {
      answers,
      form,
      savedAt: new Date().toISOString(),
      ...(idempotencyKey === undefined ? {} : { idempotencyKey }),
    };
    await setMeta('formDrafts', { ...drafts, [formId]: next });
  });
}

export async function dropDraft(formId: string): Promise<void> {
  await db.transaction('rw', db.meta, async () => {
    const drafts = await getMeta('formDrafts');
    if (!(formId in drafts)) return;
    const rest = { ...drafts };
    // eslint-disable-next-line @typescript-eslint/no-dynamic-delete -- a record keyed by form id
    delete rest[formId];
    await setMeta('formDrafts', rest);
  });
}
