/**
 * The rules of answering a form, kept out of the screen so they can be
 * tested on their own: what counts as answered, what a missing answer is
 * called, how long the form takes, and the body the server is sent.
 *
 * The server checks every answer again (400 `invalid_answer`); these only
 * decide what the screen says before anything is sent.
 */
import type { ApiForm, ApiFormAnswerInput, ApiFormQuestion } from '@/api/types.js';
import type { MessageKey } from '@/i18n/index.js';

/** An option id (single), option ids (multi), 1–5 (rating) or text. */
export type AnswerValue = string | string[] | number;
export type Answers = Record<string, AnswerValue>;

/**
 * Text limits, the contract's (`FormQuestionType`: short_text up to 200,
 * long_text up to 2000). Written here because a text field must stop at the
 * server's limit as it is typed; the server refuses longer text anyway.
 */
export const SHORT_TEXT_MAX = 200;
export const LONG_TEXT_MAX = 2000;

/** The counter under a text field appears at this share of its limit (design §3.2). */
export const COUNT_FROM = 0.8;

/** "About n min": a question takes about this many minutes (design §3.1). */
export const MINUTES_PER_QUESTION = 0.4;

/** The lowest and highest point of a rating question (contract: 1 to 5). */
export const RATING_POINTS = [1, 2, 3, 4, 5] as const;

export function textMax(question: Pick<ApiFormQuestion, 'type'>): number {
  return question.type === 'long_text' ? LONG_TEXT_MAX : SHORT_TEXT_MAX;
}

export function minutesFor(questions: number): number {
  return Math.max(1, Math.round(questions * MINUTES_PER_QUESTION));
}

function optionIds(question: ApiFormQuestion): Set<string> {
  return new Set((question.options ?? []).map((option) => option.id));
}

/** Whether a value answers the question; whitespace-only text does not. */
export function isAnswered(question: ApiFormQuestion, value: AnswerValue | undefined): boolean {
  switch (question.type) {
    case 'single':
      return typeof value === 'string' && optionIds(question).has(value);
    case 'multi': {
      if (!Array.isArray(value) || value.length === 0) return false;
      const ids = optionIds(question);
      return value.every((id) => ids.has(id));
    }
    case 'rating':
      return typeof value === 'number' && Number.isInteger(value) && value >= 1 && value <= 5;
    case 'short_text':
    case 'long_text':
      return typeof value === 'string' && value.trim() !== '' && value.length <= textMax(question);
  }
}

/** The words for a required question left unanswered. */
export function errorKey(question: ApiFormQuestion): MessageKey {
  switch (question.type) {
    case 'single':
      return 'form.err.single';
    case 'multi':
      return 'form.err.multi';
    case 'rating':
      return 'form.err.rating';
    case 'short_text':
    case 'long_text':
      return 'form.err.text';
  }
}

/** Every required question without an answer, by id, in the form's order. */
export function missingAnswers(
  form: Pick<ApiForm, 'questions'>,
  answers: Answers,
): Record<string, MessageKey> {
  const errors: Record<string, MessageKey> = {};
  for (const question of form.questions) {
    if (question.required && !isAnswered(question, answers[question.id]))
      errors[question.id] = errorKey(question);
  }
  return errors;
}

/**
 * The answers kept from a draft for the form as it is now: a question that
 * is gone, or a choice that no longer exists, is dropped. Half-typed text is
 * kept even when blank, so the field shows what was typed.
 */
export function keepFitting(form: Pick<ApiForm, 'questions'>, answers: Answers): Answers {
  const kept: Answers = {};
  for (const question of form.questions) {
    const value = answers[question.id];
    if (value === undefined) continue;
    const textType = question.type === 'short_text' || question.type === 'long_text';
    if (textType ? typeof value === 'string' : isAnswered(question, value)) {
      kept[question.id] = textType && typeof value === 'string' ? value.slice(0, textMax(question)) : value;
    }
  }
  return kept;
}

/** The body for POST /forms/{id}/answers: answered questions only, text trimmed. */
export function answerInput(form: Pick<ApiForm, 'questions'>, answers: Answers): ApiFormAnswerInput {
  const out: ApiFormAnswerInput['answers'] = [];
  for (const question of form.questions) {
    const value = answers[question.id];
    if (!isAnswered(question, value)) continue;
    switch (question.type) {
      case 'single':
        out.push({ questionId: question.id, optionId: value as string });
        break;
      case 'multi': {
        // In the form's order, whatever order they were ticked in.
        const chosen = new Set(value as string[]);
        out.push({
          questionId: question.id,
          optionIds: (question.options ?? []).map((option) => option.id).filter((id) => chosen.has(id)),
        });
        break;
      }
      case 'rating':
        out.push({ questionId: question.id, rating: value as number });
        break;
      case 'short_text':
      case 'long_text':
        out.push({ questionId: question.id, text: (value as string).trim() });
        break;
    }
  }
  return { answers: out };
}

/**
 * The day a form stopped taking answers, when it has one that has passed
 * (`closesOn` is a calendar day; a form closed by hand before it has none
 * to show). `today` is YYYY-MM-DD.
 */
export function closedOn(form: Pick<ApiForm, 'closesOn'>, today: string): string | undefined {
  return form.closesOn !== undefined && form.closesOn <= today ? form.closesOn : undefined;
}
